const D = { density:.55, energy:.6, speed:1, scale:1, flow:.6, hue:195, x:.5, y:.5, style:'neon', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU=Math.PI*2, HP=Math.PI/2, PIc=Math.PI;
const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const md=(a,n)=>((a%n)+n)%n;
const seed=P.seed|0;
const h2=(gx,gy)=>{const s=Math.sin(gx*127.1+gy*311.7+seed*74.13)*43758.5453;return s-Math.floor(s);};
const fr=i=>{const s=Math.sin(i*97.3+seed*57.7)*24634.6345;return s-Math.floor(s);};

const W=width, Hh=height, u=Math.min(W,Hh);
const style=P.style;
const neon = style==='neon';
const circuit = style==='circuit';
const glass = style==='glass';
const opart = style==='opart';
const rope = style==='rope';

const av=clp(P.alpha,0,100)/100;
const dens=clp(P.density,0,1);
const en=clp(P.energy,0,1);
const intn=(K.intensity!=null?K.intensity:.6);
const sec=K.section||0;
const glow=en*(0.5+0.7*intn);
const flow=clp(P.flow,0,1);

const ts=Math.max(u*0.055, u*(0.17-dens*0.11));
const half=ts*0.5;
const swb=ts*(neon?0.11:glass?0.12:opart?0.14:rope?0.05:0.08)*clp(P.scale,0.4,2.4);

const sv=u*0.005*P.speed;
const dirA=0.55+fr(3)*1.2;
const ox=K.t*sv*Math.cos(dirA);
const oy=K.t*sv*Math.sin(dirA);

const hueDrift=K.t*3.0+sec*22;
const ax=P.x*W, ay=P.y*Hh;
const wl=ts*3.2;

let bgH,bgS,bgB;
if(opart){ bgH=md(P.hue+20,360); bgS=6; bgB=82; }
else if(circuit){ bgH=135; bgS=48; bgB=11; }
else if(glass){ bgH=md(P.hue+200,360); bgS=45; bgB=8; }
else if(rope){ bgH=28; bgS=45; bgB=9; }
else { bgH=md(P.hue,360); bgS=58; bgB=6; }

blendMode(BLEND); noStroke();
fill(bgH,bgS,bgB,100*av); rect(0,0,W,Hh);
if(!opart){
  const gh=md(P.hue+(neon?45:glass?190:rope?12:120),360);
  for(let r=0;r<3;r++){ fill(gh, neon?55:35, neon?26:20, 7*av); ellipse(ax,ay, u*(1.5-r*0.35), u*(1.1-r*0.3)); }
}

if(neon) blendMode(ADD); else blendMode(BLEND);
strokeCap(ROUND); noFill();
const gx0=Math.floor((ox-ts)/ts), gx1=Math.floor((ox+W+ts)/ts);
const gy0=Math.floor((oy-ts)/ts), gy1=Math.floor((oy+Hh+ts)/ts);
let drawn=0;
for(let gy=gy0; gy<=gy1; gy++){
  for(let gx=gx0; gx<=gx1; gx++){
    if(drawn++>4200) break;
    const cxp=gx*ts-ox+half, cyp=gy*ts-oy+half;
    const base=h2(gx,gy)>0.5?1:0;
    const ph=h2(gx*1.7+5.3, gy*0.7+9.1);
    const rt=0.3+0.7*h2(gx*2.3+1.1, gy*2.9+4.4);
    const spin=K.t*P.speed*0.026*(0.4+1.4*en)*rt + ph*4;
    const st4=Math.floor(spin); let frc=spin-st4;
    let fe=frc<0.78?0:(frc-0.78)/0.22; fe=fe*fe*(3-2*fe);
    const ang=(base+st4+fe)*HP;
    const posH=md(P.hue + (gx*10 + gy*14) + hueDrift, 360);
    const dsx=cxp-ax, dsy=cyp-ay, dist=Math.hypot(dsx,dsy);
    const rip=0.5+0.5*Math.sin(dist/wl*TAU - K.t*1.4*P.speed);
    const briBoost=flow*0.5*rip + K.pulse*0.22*en + A.bass*0.5*en;
    push(); translate(cxp,cyp); rotate(ang); noFill(); strokeCap(ROUND);
    if(neon){
      const b=clp(48+glow*38+briBoost*45,0,100);
      stroke(posH,72,b*0.9,(14+glow*9)*av); strokeWeight(swb*2.6);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
      stroke(posH,42,clp(b+22,0,100),(48+glow*30)*av); strokeWeight(swb);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
    } else if(circuit){
      const cu=md(30+(gx*2+gy)*1.3,360), b=clp(60+briBoost*30,0,100);
      stroke(md(cu-6,360),60,20,100*av); strokeWeight(swb*1.8);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
      stroke(cu,82,b,100*av); strokeWeight(swb);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
      stroke(cu,26,clp(b+28,0,100),75*av); strokeWeight(swb*0.32);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
      if(h2(gx*3.1,gy*5.7)>0.72){ noStroke(); fill(cu,68,clp(b+8,0,100),100*av); circle(0,0,swb*2.4); fill(135,48,9,100*av); circle(0,0,swb*1.0); }
    } else if(glass){
      const b=clp(58+briBoost*30+glow*10,30,95);
      stroke(md(P.hue+200,360),25,5,100*av); strokeWeight(swb*1.45);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
      stroke(posH,80,b,100*av); strokeWeight(swb*0.85);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
      stroke(posH,38,clp(b+24,0,100),58*av); strokeWeight(swb*0.24);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
    } else if(opart){
      stroke(0,0,7,100*av); strokeWeight(swb);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
    } else {
      const rh=md(30+(h2(gx,gy)-0.5)*34,360), b=clp(56+briBoost*24,0,100);
      stroke(md(rh-6,360),58,18,100*av); strokeWeight(swb*3.4);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
      stroke(rh,54,b,100*av); strokeWeight(swb*2.5);
      arc(-half,-half,ts,ts,0,HP); arc(half,half,ts,ts,PIc,PIc+HP);
      stroke(rh,24,clp(b+30,0,100),90*av); strokeWeight(swb*0.8);
      arc(-half,-half,ts*0.86,ts*0.86,0,HP); arc(half,half,ts*0.86,ts*0.86,PIc,PIc+HP);
    }
    pop();
  }
  if(drawn>4200) break;
}

if(A.treble>0.05){
  blendMode(ADD); noStroke();
  const nsp=Math.floor(16*A.treble);
  for(let i=0;i<nsp;i++){ const gsx=fr(i*2.1+Math.floor(K.beat*2))*W, gsy=fr(i*3.3+9+Math.floor(K.beat*2))*Hh; fill(md(P.hue+80,360),40,100,50*A.treble*av); circle(gsx,gsy,u*0.007); }
}
blendMode(BLEND); drawingContext.shadowBlur=0;
